import { describe, expect, it } from 'vitest';

import { add } from './dogfood-add.js';

describe('dogfood arithmetic', () => {
  it('adds two declared operands', () => {
    expect(add(2, 3)).toBe(5);
  });
});

import { describe, expect, it } from 'vitest';

import { canonicalJson } from './canonical-json.js';

describe('canonicalJson', () => {
  it('sorts object keys recursively without changing array order', () => {
    expect(canonicalJson({ z: 1, a: { d: 2, c: [3, 1] } }))
      .toBe('{"a":{"c":[3,1],"d":2},"z":1}');
  });

  it('rejects values that JSON cannot represent deterministically', () => {
    expect(() => canonicalJson({ value: undefined })).toThrow(/undefined/u);
    expect(() => canonicalJson(Number.NaN)).toThrow(/finite/u);
    expect(() => canonicalJson(Symbol('not-json'))).toThrow(/not JSON serializable/u);
  });
});

import { describe, expect, it } from 'vitest';

import type { Diagnosis } from '../domain.js';
import { adjudicate } from './adjudicate.js';

const DIAGNOSIS: Diagnosis = {
  class: 'test-assertion',
  confidence: 0.9,
  signals: ['assertion'],
  failingCmd: 'pnpm test',
  errorExcerpt: 'expected 1 to be 2',
};

describe('adjudicate', () => {
  it.each([
    ['approved', { reasoning: 'The patch fixes the diagnosed assertion.' }],
    ['reasoning', { approved: true }],
  ])('refuses an Ultra reply without required field %s', async (_field, reply) => {
    const result = await adjudicate({
      async chat() {
        return { text: JSON.stringify(reply) };
      },
    }, {
      diagnosis: DIAGNOSIS,
      diff: 'diff --git a/add.ts b/add.ts\n',
      beforeLog: 'AssertionError',
      afterLog: 'Tests passed',
    });
    expect(result).toEqual({
      approved: false,
      reasoning: expect.stringContaining('REFUSED'),
    });
  });
});

import { describe, expect, it } from 'vitest';

import { TavilyClient } from './tavily.js';

const LIVE = process.env.SUTURA_LIVE === '1';

describe.skipIf(!LIVE)('Tavily live search', () => {
  it('returns a relevant citation for a Vitest assertion error', async () => {
    const tavily = new TavilyClient(process.env.TAVILY_API_KEY);

    const citations = await tavily.search(
      'Vitest AssertionError expected value to equal received value debugging',
      { maxResults: 3 },
    );

    expect(citations.length).toBeGreaterThanOrEqual(1);
    expect(citations[0]).toMatchObject({
      title: expect.any(String),
      url: expect.stringMatching(/^https?:\/\//),
      snippet: expect.any(String),
    });
    expect(
      citations.some((citation) =>
        /vitest|assert|expect|test/i.test(`${citation.title} ${citation.snippet}`),
      ),
    ).toBe(true);
  });
});

export function add(left: number, right: number): number {
  return left - right;
}

export class CanonicalJsonError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'CanonicalJsonError';
  }
}

export function canonicalJson(value: unknown, path = '$'): string {
  if (value === null || typeof value === 'boolean' || typeof value === 'string') {
    return JSON.stringify(value);
  }
  if (typeof value === 'number') {
    if (!Number.isFinite(value)) throw new CanonicalJsonError(`${path} must be finite`);
    return JSON.stringify(value);
  }
  if (Array.isArray(value)) {
    return `[${value.map((item, index) => canonicalJson(item, `${path}[${index}]`)).join(',')}]`;
  }
  if (typeof value === 'object') {
    const prototype = Object.getPrototypeOf(value) as unknown;
